#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char *name;
    int score;
    struct Node *next;
} Node;

Node *add_last(Node *head, char *name, int score) {
    Node *fresh = malloc(sizeof(Node));
    if (fresh == NULL) {
        return head;
    }
    fresh->name = name;
    fresh->score = score;
    fresh->next = NULL;
    if (head == NULL) {
        return fresh;
    }
    Node *p = head;
    while (p->next != NULL) {
        p = p->next;
    }
    p->next = fresh;
    return head;
}

Node *find_by_name(Node *head, char *name) {
    for (Node *p = head; p != NULL; p = p->next) {
        if (strcmp(p->name, name) == 0) {
            return p;
        }
    }
    return NULL;
}

int main(void) {
    Node *head = NULL;
    head = add_last(head, "{n1}", {s1});
    head = add_last(head, "{n2}", {s2});

    char want[16];
    strcpy(want, "{n1}");
    Node *it = find_by_name(head, want);
    if (it != NULL) {
        printf("找到：%s %d 分\n", it->name, it->score);
    } else {
        printf("名单里没有这位喵\n");
    }
    return 0;
}
